diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..22483e4 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -30,6 +30,49 @@ test("RF-003: una factura emitida no se puede modificar", () => {
   assert.throws(() => { "use strict"; f.totalCentavos = 1; }, TypeError);
 });

+const LINEAS = [
+  { cantidad: 2, precioUnitarioCentavos: 5000 },
+  { cantidad: 1, precioUnitarioCentavos: 1050 },
+];
+
+test("RF-006-T1: descuento global del 10 %", () => {
+  assert.deepEqual(calcularFactura(LINEAS, { descuentoGlobal: 10 }), {
+    totalCentavos: 9945, ivaCentavos: 1293, netoCentavos: 8652, descuentoGlobalCentavos: 1105,
+  });
+});
+
+test("RF-006-T2: sin descuento global el resultado no cambia", () => {
+  const base = { totalCentavos: 11050, ivaCentavos: 1437, netoCentavos: 9613 };
+  assert.deepEqual(calcularFactura(LINEAS), base);
+  assert.deepEqual(calcularFactura(LINEAS, {}), base);
+});
+
+test("RF-006-T3: 0 % no cambia el total y 100 % lo deja en 0", () => {
+  assert.equal(calcularFactura(LINEAS, { descuentoGlobal: 0 }).totalCentavos, 11050);
+  assert.deepEqual(calcularFactura(LINEAS, { descuentoGlobal: 100 }), {
+    totalCentavos: 0, ivaCentavos: 0, netoCentavos: 0, descuentoGlobalCentavos: 11050,
+  });
+});
+
+test("RF-006-T4: descuento global inválido se rechaza", () => {
+  for (const d of [-1, 101, NaN, "10", null, Infinity]) {
+    assert.throws(() => calcularFactura(LINEAS, { descuentoGlobal: d }), RangeError, String(d));
+  }
+});
+
+test("RF-006-T5: el resultado son centavos enteros con porcentajes fraccionarios", () => {
+  const f = calcularFactura(LINEAS, { descuentoGlobal: 3.33 });
+  for (const v of Object.values(f)) assert.ok(Number.isInteger(v));
+  assert.equal(f.totalCentavos + f.descuentoGlobalCentavos, 11050);
+});
+
+test("RF-006-T6: emitirFactura con descuento global queda congelada", () => {
+  const f = emitirFactura({ numero: 8, nit: "1023456", razonSocial: "Cliente SA", items: LINEAS, descuentoGlobal: 10 });
+  assert.ok(Object.isFrozen(f));
+  assert.equal(f.totalCentavos, 9945);
+  assert.equal(f.descuentoGlobalCentavos, 1105);
+});
